import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../application/itqan_journey_provider.dart';
import '../../data/journey_content_repository.dart';
import '../../../quran/models/ayah.dart';

class QuranJourneyScreen extends ConsumerStatefulWidget { const QuranJourneyScreen({super.key}); @override ConsumerState<QuranJourneyScreen> createState()=>_QuranJourneyScreenState(); }
class _QuranJourneyScreenState extends ConsumerState<QuranJourneyScreen> {
 final _repository=JourneyQuranRepository(); List<Surah> _surahs=[]; List<Ayah> _ayahs=[]; int _surah=1,_startAyah=1; int? _sessionStart; bool _loading=true,_saving=false; final _pagesController=TextEditingController();
 @override void initState(){super.initState();_initialize();}
 @override void dispose(){_pagesController.dispose();super.dispose();}
 Future<void> _initialize()async{try{_surahs=await _repository.surahs();_surah=await _repository.lastSurah();_ayahs=await _repository.ayahs(_surah);_startAyah=(await _repository.lastAyah()).clamp(1,_ayahs.length);_sessionStart=_startAyah;}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('تعذر تحميل المصحف: $e')));}finally{if(mounted)setState(()=>_loading=false);}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('قرآن الرحلة')),body:_loading?const Center(child:CircularProgressIndicator()):Column(children:[Padding(padding:const EdgeInsets.all(12),child:Row(children:[Expanded(child:DropdownButton<int>(isExpanded:true,value:_surah,items:_surahs.map((s)=>DropdownMenuItem(value:s.number,child:Text('${s.number}. ${s.nameArabic}'))).toList(),onChanged:(v){if(v!=null)_selectSurah(v);})),const SizedBox(width:8),DropdownButton<int>(value:_startAyah,items:List.generate(_ayahs.length,(i)=>DropdownMenuItem(value:i+1,child:Text('آية ${i+1}'))),onChanged:(v)async{if(v!=null){setState(()=>_startAyah=v);await _repository.savePosition(_surah,v);}})])),Expanded(child:ListView.builder(itemCount:_ayahs.length,itemBuilder:(context,i)=>ListTile(leading:Text('${i+1}'),title:Text(_ayahs[i].textUthmani,textDirection:TextDirection.rtl,style:Theme.of(context).textTheme.headlineSmall),onTap:()=>_save(i+1)))),Padding(padding:const EdgeInsets.fromLTRB(16,8,16,16),child:Row(children:[SizedBox(width:96,child:TextField(controller:_pagesController,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'الصفحات',border:OutlineInputBorder()))),const SizedBox(width:12),Expanded(child:FilledButton(onPressed:_saving?null:_recordRead,child:Text(_saving?'جارٍ التسجيل':'تسجيل جلسة القراءة')))]))]));
 Future<void> _selectSurah(int n)async{setState(()=>_loading=true);try{_ayahs=await _repository.ayahs(n);_surah=n;_startAyah=1;_sessionStart=1;await _repository.savePosition(n,1);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}finally{if(mounted)setState(()=>_loading=false);}}
 Future<void> _save(int ayah)async{setState(()=>_startAyah=ayah);await _repository.savePosition(_surah,ayah);}
 Future<void> _recordRead()async{final pages=int.tryParse(_pagesController.text.trim());if(pages==null||pages<1){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('أدخل عدد الصفحات التي قرأتها فعلياً.')));return;}if(_sessionStart==null||_startAyah<=_sessionStart!){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تابع القراءة في هذه الجلسة قبل تسجيل الإنجاز.')));return;}setState(()=>_saving=true);try{await _repository.savePosition(_surah,_startAyah);final result=await ref.read(itqanJourneyProvider.notifier).recordActivity('quran.reading',metadata:{'pages':pages});if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('قبل الخادم جلسة القراءة • ${result['data']?['xp_earned']??0} XP')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('لم يقبل الخادم النشاط: $e')));}finally{if(mounted)setState(()=>_saving=false);}}
}
